const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { saveNote } = require('../save-note.cjs');
test('create parent directories and write the file itself', () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(),'dispatch-note-'));
  try {
    const target = path.join(root,'records','night','dispatch.txt');
    let returned;
    assert.doesNotThrow(() => { returned = saveNote(target,'已发车\n车次 18'); });
    assert.equal(returned,target);
    assert.equal(fs.statSync(target).isFile(),true);
    assert.equal(fs.readFileSync(target,'utf8'),'已发车\n车次 18');
    assert.equal(saveNote(target,'updated'),target);
    assert.equal(fs.readFileSync(target,'utf8'),'updated');
    const sibling = path.join(root,'records','night','empty.txt');
    saveNote(sibling,''); assert.equal(fs.readFileSync(sibling,'utf8'),'');
    const direct = path.join(root,'direct.txt');
    saveNote(direct,'ok'); assert.equal(fs.readFileSync(direct,'utf8'),'ok');
    assert.deepEqual(fs.readdirSync(path.dirname(target)).sort(), ['dispatch.txt','empty.txt']);
  } finally { fs.rmSync(root,{recursive:true,force:true}); }
});

